        beforeEach(() => {
            mocked(playback.getState).mockReturnValue(playbackState);
            renderResult = render(<VoiceBroadcastPlaybackBody playback={playback} />);
        });

        it("should render as expected", () => {
            expect(renderResult.container).toMatchSnapshot();
        });
    });
});

