describe(`when there is a ${VoiceBroadcastInfoState.Resumed} broadcast without chunks yet`, () => {
    beforeEach(async () => {
        // info relation
        mocked(client.relations).mockResolvedValueOnce({ events: [] });
        setUpChunkEvents([]);
        infoEvent = mkInfoEvent(VoiceBroadcastInfoState.Resumed);
        playback = await mkPlayback();
    });

    it("should start without a live badge", () => {
        expect(playback.getLiveness()).toBe("not-live");
    });

    describe("and calling start", () => {
        startPlayback();

        it("should be in buffering state", () => {
            expect(playback.getState()).toBe(VoiceBroadcastPlaybackState.Buffering);
        });

        it("should be grey while waiting for the first chunk", () => {
            expect(playback.getLiveness()).toBe("grey");
            expect(onLivenessChanged).toHaveBeenCalledTimes(1);
            expect(onLivenessChanged).toHaveBeenCalledWith("grey");
        });

        it("should have duration 0", () => {
            expect(playback.durationSeconds).toBe(0);
        });

        it("should be at time 0", () => {
            expect(playback.timeSeconds).toBe(0);
        });

        describe("and calling stop", () => {
            stopPlayback();
            itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Stopped);

            it("should no longer show a badge", () => {
                expect(playback.getLiveness()).toBe("not-live");
                expect(onLivenessChanged).toHaveBeenLastCalledWith("not-live");
            });

            describe("and calling pause", () => {
                pausePlayback();
                // stopped voice broadcasts cannot be paused
                itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Stopped);
            });
        });

        describe("and calling pause", () => {
            pausePlayback();
            itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Paused);

            it("should remain grey without a playing chunk", () => {
                expect(playback.getLiveness()).toBe("grey");
                expect(onLivenessChanged).toHaveBeenCalledTimes(1);
            });
        });

        describe("and receiving the first chunk", () => {
            beforeEach(() => {
                // TODO Michael W: Use RelationsHelper
                // @ts-ignore
                playback.chunkRelationHelper.emit(RelationsHelperEvent.Add, chunk1Event);
            });

            itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Playing);

            it("should become live when the chunk plays", () => {
                expect(playback.getLiveness()).toBe("live");
                expect(onLivenessChanged).toHaveBeenLastCalledWith("live");
            });

            it("should update the duration", () => {
                expect(playback.durationSeconds).toBe(2.3);
            });

            it("should play the first chunk", () => {
                expect(chunk1Playback.play).toHaveBeenCalled();
            });
        });
    });
});

describe(`when there is a ${VoiceBroadcastInfoState.Resumed} voice broadcast with some chunks`, () => {
    beforeEach(async () => {
        // info relation
        mocked(client.relations).mockResolvedValueOnce({ events: [] });
        setUpChunkEvents([chunk2Event, chunk1Event]);
        infoEvent = mkInfoEvent(VoiceBroadcastInfoState.Resumed);
        playback = await mkPlayback();
    });

    it("durationSeconds should have the length of the known chunks", () => {
        expect(playback.durationSeconds).toEqual(6.5);
    });

    it("should not show a badge until playback starts", () => {
        expect(playback.getLiveness()).toBe("not-live");
    });

    describe("and an event with the same transaction Id occurs", () => {
        beforeEach(() => {
            // @ts-ignore
            playback.chunkRelationHelper.emit(RelationsHelperEvent.Add, chunk2BEvent);
        });

        it("durationSeconds should not change", () => {
            expect(playback.durationSeconds).toEqual(6.5);
            expect(onLengthChanged).not.toHaveBeenCalled();
        });
    });

    describe("and calling start", () => {
        startPlayback();

        it("should be live while playing the current chunk", () => {
            expect(playback.getLiveness()).toBe("live");
            expect(onLivenessChanged).toHaveBeenLastCalledWith("live");
        });

        it("should play the last chunk", () => {
            // assert that the last chunk is played first
            expect(chunk2Playback.play).toHaveBeenCalled();
            expect(chunk1Playback.play).not.toHaveBeenCalled();
        });

        describe("and the playback of the last chunk ended", () => {
            beforeEach(() => {
                chunk2Playback.emit(PlaybackState.Stopped);
            });

            itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Buffering);

            it("should become grey while awaiting another chunk", () => {
                expect(playback.getLiveness()).toBe("grey");
                expect(onLivenessChanged).toHaveBeenLastCalledWith("grey");
            });

            describe("and the next chunk arrived", () => {
                beforeEach(() => {
                    // TODO Michael W: Use RelationsHelper
                    // @ts-ignore
                    playback.chunkRelationHelper.emit(RelationsHelperEvent.Add, chunk3Event);
                });

                itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Playing);

                it("should become live again", () => {
                    expect(playback.getLiveness()).toBe("live");
                    expect(onLivenessChanged).toHaveBeenLastCalledWith("live");
                });

                it("should play the next chunk", () => {
                    expect(chunk3Playback.play).toHaveBeenCalled();
                });
            });
        });

        it("should follow broadcast pause, resume and end info events", () => {
            const emitInfoState = (state: VoiceBroadcastInfoState, timestamp: number) => {
                const event = mkInfoEvent(state);
                jest.spyOn(event, "getTs").mockReturnValue(timestamp);
                // @ts-ignore
                playback.infoRelationHelper.emit(RelationsHelperEvent.Add, event);
            };

            emitInfoState(VoiceBroadcastInfoState.Paused, 1);
            expect(playback.getLiveness()).toBe("grey");
            emitInfoState(VoiceBroadcastInfoState.Paused, 2);
            expect(onLivenessChanged).toHaveBeenCalledTimes(3); // buffering, live, grey

            emitInfoState(VoiceBroadcastInfoState.Resumed, 3);
            expect(playback.getLiveness()).toBe("live");
            emitInfoState(VoiceBroadcastInfoState.Stopped, 4);
            expect(playback.getLiveness()).toBe("not-live");
            expect(onLivenessChanged.mock.calls.map(([value]) => value)).toEqual([
                "grey", "live", "grey", "live", "not-live",
            ]);
        });
    });
});

